    21    PosibErr<void> DocumentChecker
    22    ::setup(Tokenizer * tokenizer, Speller * speller, Filter * filter)
    23    {
    24      tokenizer_.reset(tokenizer);
    25      filter_.reset(filter);
    26      speller_ = speller;
    27      conv_ = speller->to_internal_;
    28      return no_err;
    29    }
    30
    31    void DocumentChecker::set_status_fun(void (* sf)(void *, Token, int),
    32                                         void * d)
    33    {
    34      status_fun_ = sf;
    35      status_fun_data_ = d;
    36    }
    37
    38    void DocumentChecker::reset()
    39    {
    40      if (filter_)
    41        filter_->reset();
    42    }
    43
    44    void DocumentChecker::process(const char * str, int size)
    45    {
    46      proc_str_.clear();
    47      conv_->decode(str, size, proc_str_);
    48      proc_str_.append(0);
    49      FilterChar * begin = proc_str_.pbegin();
    50      FilterChar * end   = proc_str_.pend() - 1;
    51      if (filter_)
    52        filter_->process(begin, end);
    53      tokenizer_->reset(begin, end);
    54    }
    55
    56    Token DocumentChecker::next_misspelling()
    57    {
    58      bool correct;
    59      Token tok;
    60      do {
    61        if (!tokenizer_->advance()) {
    62          tok.offset = proc_str_.size();
    63          tok.len = 0;
    64          return tok;
    65        }
    66        correct = speller_->check(MutableString(tokenizer_->word.data(),
    67                                                tokenizer_->word.size() - 1));
    68        tok.len  = tokenizer_->end_pos - tokenizer_->begin_pos;
    69        tok.offset = tokenizer_->begin_pos;
    70        if (status_fun_)
    71          (*status_fun_)(status_fun_data_, tok, correct);
    72      } while (correct);
    73      return tok;
    74    }
